CREATE OR REPLACE FUNCTION public.record_figures(c creature)
 RETURNS TABLE(stat text, value double precision)
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  return query
    select s.stat, blood_at_birth(c, s.stat) from unnest(array['hardy', 'tough', 'speed', 'work']) s(stat)
